mapper.select:
SELECT COUNT(*) FROM learning_units lu
JOIN path_stages ps ON lu.stage_id = ps.id
WHERE ps.path_id = #{pathId}

mapper.update:
UPDATE user_progress
SET last_study_time = NOW(), status = 'IN_PROGRESS', visit_count = COALESCE(visit_count, 0) + 1
WHERE user_id = #{userId} AND unit_id = #{unitId}

UPDATE user_progress
SET study_duration = COALESCE(study_duration, 0) + #{seconds}
WHERE user_id = #{userId} AND unit_id = #{unitId}

UPDATE user_progress
SET rating = #{rating}
WHERE user_id = #{userId} AND unit_id = #{unitId}

UPDATE user_progress
SET is_favorite = #{isFavorite}
WHERE user_id = #{userId} AND unit_id = #{unitId}

mapper.select:
SELECT p.id, p.user_id AS userId, p.unit_id AS unitId, p.path_id AS pathId, 
       p.status, p.start_time AS startTime, p.last_study_time AS lastStudyTime
FROM user_progress p
WHERE p.user_id = #{userId}
ORDER BY p.last_study_time DESC
LIMIT #{limit}

SELECT COUNT(*) FROM user_progress
WHERE status = 'COMPLETED' 
AND complete_time >= #{startDate} 
AND complete_time < #{endDate}

SELECT COUNT(*) FROM user_progress
WHERE last_study_time >= #{startDate} 
AND last_study_time < #{endDate}

SELECT last_study_time FROM user_progress
WHERE user_id = #{userId}
ORDER BY last_study_time DESC
